    return [digit for digit in (2, 4, 6, 8) if a <= digit <= b]


def strict_endpoints(a: int, b: int) -> list[int]:
    low, high = min(a, b), max(a, b)
    return [digit for digit in (2, 4, 6, 8) if low < digit < high]


def hard_coded(_a: int, _b: int) -> list[int]:
